artifacts.solve_py:
import os
import sys
import csv
import json
import math

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
SOL_PATH = os.path.join(OUT_DIR, "solution.csv")

# ----------------------------------------------------------------------
# Data loading
# ----------------------------------------------------------------------

def load_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    staging = {}
    with open(os.path.join(DATA_DIR, "staging_points.csv")) as f:
        for row in csv.DictReader(f):
            staging[row["node_id"]] = {
                "name": row["node_name"],
                "clearance": row["launch_clearance"].strip(),
                "ramp": int(row["boat_ramp"]),
                "handling": float(row["handling_minutes"]),
            }

    edges = []
    with open(os.path.join(DATA_DIR, "road_edges.csv")) as f:
        for row in csv.DictReader(f):
            if int(row["usable_after_flood"]) == 1:
                edges.append((row["from_node"], row["to_node"], float(row["travel_minutes"])))

    shelters = {}
    with open(os.path.join(DATA_DIR, "shelters.csv")) as f:
        for row in csv.DictReader(f):
            shelters[row["shelter_id"]] = {
                "name": row["shelter_name"],
                "area": row["area_type"].strip(),
                "dry_node": row["nearest_dry_node"].strip(),
                "demand": float(row["demand_kg"]),
                "priority": row["priority"].strip(),
                "deadline": float(row["deadline_minutes"]),
            }

    drone_opts = []
    with open(os.path.join(DATA_DIR, "drone_options.csv")) as f:
        for row in csv.DictReader(f):
            if int(row["payload_feasible"]) == 1:
                flight = float(row["flight_minutes"])
                if flight + cfg["drone_setup_minutes"] <= cfg["drone_endurance_minutes"]:
                    drone_opts.append({
                        "shelter": row["shelter_id"],
                        "launch": row["launch_node"],
                        "flight": flight,
                        "risk": float(row["landing_risk"]),
                    })

    boat = {}
    with open(os.path.join(DATA_DIR, "boat_travel.csv")) as f:
        for row in csv.DictReader(f):
            boat[(row["from_id"], row["to_id"])] = float(row["minutes"])

    weights = {}
    with open(os.path.join(DATA_DIR, "priority_weights.csv")) as f:
        for row in csv.DictReader(f):
            weights[row["priority"].strip()] = float(row["weight"])

    weather = []
    with open(os.path.join(DATA_DIR, "weather_windows.csv")) as f:
        for row in csv.DictReader(f):
            weather.append({
                "start": float(row["start_minute"]),
                "end": float(row["end_minute"]),
                "drone": float(row["drone_multiplier"]),
                "boat": float(row["boat_multiplier"]),
            })

    return cfg, staging, edges, shelters, drone_opts, boat, weights, weather


def main():
    cfg, staging, edges, shelters, drone_opts, boat, weights, weather = load_data()

    depot = cfg["depot_id"]
    S = [depot] + sorted(n for n in staging if n != depot)
    nS = len(S)
    idx = {s: i for i, s in enumerate(S)}

    H = sorted(shelters.keys())
    Hdry = [h for h in H if shelters[h]["area"] == "dry"]
    Hfl = [h for h in H if shelters[h]["area"] == "flooded"]

    ramps = [s for s in S if staging[s]["ramp"] == 1]
    good_clear = [s for s in S if staging[s]["clearance"] != "poor"]

    # Drone options filtered by clearance
    drone_opts = [o for o in drone_opts if o["launch"] in good_clear]

    # Boat travel helpers
    def btime(a, b):
        if (a, b) in boat:
            return boat[(a, b)]
        if (b, a) in boat:
            return boat[(b, a)]
        return None

    # Precompute boat trip feasibility: enumerate all ordered sequences of flooded
    # shelters (length 1..4) from each ramp with load <= 96 and duration <= 115.
    # Duration = setup 10 + travel (ramp->h1 + h1->h2 + ... ) + 4*n
    MAXTRIPLEN = 4
    trips_by_ramp = {r: [] for r in ramps}
    for r in ramps:
        # candidate shelters reachable from r
        cand = [h for h in Hfl if btime(r, h) is not None]
        n = len(cand)

        def rec(path, load):
            if len(path) >= 1:
                dur = cfg["boat_setup_minutes"] + cfg["boat_unload_minutes_per_shelter"] * len(path)
                prev = r
                for h in path:
                    t = btime(prev, h)
                    if t is None:
                        return
                    dur += t
                    prev = h
                if dur <= cfg["boat_trip_limit_minutes"] + 1e-9:
                    trips_by_ramp[r].append((tuple(path), dur))
            if len(path) >= MAXTRIPLEN:
                return
            for h in cand:
                if h in path:
                    continue
                if load + shelters[h]["demand"] > cfg["boat_capacity_kg"] + 1e-9:
                    continue
                if btime(path[-1] if path else r, h) is None:
                    continue
                rec(path + [h], load + shelters[h]["demand"])

        rec([], 0.0)

    # Deduplicate trips (same sequence)
    for r in ramps:
        seen = set()
        uniq = []
        for seq, dur in trips_by_ramp[r]:
            if seq not in seen:
                seen.add(seq)
                uniq.append((seq, dur))
        trips_by_ramp[r] = uniq

    # Number of trips per ramp (each physical trip used at most once)
    K = {r: len(trips_by_ramp[r]) for r in ramps}

    # ------------------------------------------------------------------
    # Model
    # ------------------------------------------------------------------
    model = Model("flood_relief")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    M = 2000.0  # big-M for time linking

    # Truck route variables
    x = {}
    for a in S:
        for b in S:
            if a == b:
                continue
            if (a, b, None) in [(e[0], e[1], None) for e in edges] or (b, a, None) in [(e[0], e[1], None) for e in edges]:
                x[(a, b)] = model.addVar(name=f"x_{a}_{b}", vtype="B", lb=0, ub=1)
    u = {}
    for s in S:
        if s == depot:
            continue
        u[s] = model.addVar(name=f"u_{s}", vtype="C", lb=0, ub=nS - 1)
    y = {}
    for s in S:
        if s == depot:
            continue
        y[s] = model.addVar(name=f"y_{s}", vtype="B", lb=0, ub=1)
    T = {}
    for s in S:
        T[s] = model.addVar(name=f"T_{s}", vtype="C", lb=0, ub=M)

    # Assignment variables
    z = {}  # truck: (h, s)
    for h in Hdry:
        s = shelters[h]["dry_node"]
        if s in staging:
            z[(h, s)] = model.addVar(name=f"z_{h}_{s}", vtype="B", lb=0, ub=1)
    d = {}  # drone: (h, o_idx)
    for oi, o in enumerate(drone_opts):
        d[(o["shelter"], oi)] = model.addVar(name=f"d_{o['shelter']}_{oi}", vtype="B", lb=0, ub=1)
    b = {}  # boat: (h, r, t_idx)
    for r in ramps:
        for ti, (seq, dur) in enumerate(trips_by_ramp[r]):
            for h in seq:
                b[(h, r, ti)] = model.addVar(name=f"b_{h}_{r}_{ti}", vtype="B", lb=0, ub=1)
    trip_used = {}
    for r in ramps:
        for ti, (seq, dur) in enumerate(trips_by_ramp[r]):
            trip_used[(r, ti)] = model.addVar(name=f"tu_{r}_{ti}", vtype="B", lb=0, ub=1)

    # Shelter completion times and lateness
    C = {}
    for h in H:
        C[h] = model.addVar(name=f"C_{h}", vtype="C", lb=0, ub=M)
    L = {}
    for h in H:
        L[h] = model.addVar(name=f"L_{h}", vtype="C", lb=0, ub=M)

    # ------------------------------------------------------------------
    # Constraints: truck routing (MTZ)
    # ------------------------------------------------------------------
    # Flow conservation at non-depot nodes
    for s in S:
        if s == depot:
            continue
        model.addCons(
            quicksum(x[(a, s)] for a in S if a != s and (a, s) in x)
            == quicksum(x[(s, a)] for a in S if a != s and (s, a) in x),
            name=f"flow_{s}",
        )
    # Depot out = 1, in = 1
    model.addCons(
        quicksum(x[(depot, b)] for b in S if b != depot and (depot, b) in x) == 1,
        name="depot_out",
    )
    model.addCons(
        quicksum(x[(a, depot)] for a in S if a != depot and (a, depot) in x) == 1,
        name="depot_in",
    )
    # y_s = inflow
    for s in S:
        if s == depot:
            continue
        model.addCons(
            y[s] == quicksum(x[(a, s)] for a in S if a != s and (a, s) in x),
            name=f"ydef_{s}",
        )
    # MTZ subtour elimination
    for a in S:
        for bb in S:
            if a == bb or (a, bb) not in x:
                continue
            if a == depot:
                model.addCons(u[bb] >= 1 - (nS - 1) * (1 - x[(a, bb)]), name=f"mtz_{a}_{bb}")
            elif bb == depot:
                continue
            else:
                model.addCons(u[bb] >= u[a] + 1 - (nS - 1) * (1 - x[(a, bb)]), name=f"mtz_{a}_{bb}")
                model.addCons(u[a] <= u[bb] - 1 + (nS - 1) * (1 - x[(a, bb)]), name=f"mtz2_{a}_{bb}")

    # ------------------------------------------------------------------
    # Assignment: each shelter exactly once
    # ------------------------------------------------------------------
    for h in H:
        terms = []
        if h in Hdry:
            s = shelters[h]["dry_node"]
            if (h, s) in z:
                terms.append(z[(h, s)])
        for oi, o in enumerate(drone_opts):
            if o["shelter"] == h:
                terms.append(d[(h, oi)])
        for r in ramps:
            for ti, (seq, dur) in enumerate(trips_by_ramp[r]):
                if h in seq:
                    terms.append(b[(h, r, ti)])
        model.addCons(quicksum(terms) == 1, name=f"assign_{h}")

    # Truck service only at visited dry node
    for (h, s), var in z.items():
        model.addCons(var <= y[s], name=f"zlink_{h}_{s}")
    # Drone only from visited launch point
    for (h, oi), var in d.items():
        o = drone_opts[oi]
        model.addCons(var <= y[o["launch"]], name=f"dlink_{h}_{oi}")
    # Boat only from visited ramp; shelter in trip iff trip used
    for (h, r, ti), var in b.items():
        model.addCons(var <= y[r], name=f"bvisit_{h}_{r}_{ti}")
        model.addCons(var <= trip_used[(r, ti)], name=f"btrip_{h}_{r}_{ti}")
    for (r, ti), tvar in trip_used.items():
        seq, dur = trips_by_ramp[r][ti]
        model.addCons(tvar <= quicksum(b[(h, r, ti)] for h in seq), name=f"tudef_{r}_{ti}")

    # ------------------------------------------------------------------
    # Timing
    # ------------------------------------------------------------------
    # Edge travel times
    etime = {}
    for (a, bb, t) in edges:
        etime[(a, bb)] = t
        etime[(bb, a)] = t

    # Truck arrival times
    for a in S:
        for bb in S:
            if a == bb or (a, bb) not in x:
                continue
            t = etime.get((a, bb))
            if t is None:
                continue
            if a == depot:
                model.addCons(T[bb] >= t - M * (1 - x[(a, bb)]), name=f"tarr_{a}_{bb}")
            else:
                model.addCons(T[bb] >= T[a] + t - M * (1 - x[(a, bb)]), name=f"tarr_{a}_{bb}")
    model.addCons(T[depot] == 0, name="tdepot")

    # Drone activity duration per staging point (sum over drone trips launched there)
    # Drone duration for option oi = setup + flight (weather multiplier applied via window)
    # For linearization with weather: use worst-case multiplier? Use P1 (1.0) base and
    # add window surcharge. Simpler: apply multiplier based on a fixed window choice.
    # We apply the multiplier of the window containing the launch departure time using
    # window binaries w_p per point.
    # Windows
    W = len(weather)
    w = {}
    for s in S:
        for p in range(W):
            w[(s, p)] = model.addVar(name=f"w_{s}_{p}", vtype="B", lb=0, ub=1)
    for s in S:
        model.addCons(quicksum(w[(s, p)] for p in range(W)) == 1, name=f"wsum_{s}")

    # Link window to departure time D_s (defined below). First define D_s.
    D = {}
    for s in S:
        D[s] = model.addVar(name=f"D_{s}", vtype="C", lb=0, ub=M)

    # Window assignment: D_s in [start_p, end_p)
    for s in S:
        for p in range(W):
            st, en = weather[p]["start"], weather[p]["end"]
            model.addCons(D[s] >= st - M * (1 - w[(s, p)]), name=f"wlo_{s}_{p}")
            model.addCons(D[s] <= en + M * (1 - w[(s, p)]), name=f"whi_{s}_{p}")

    # Drone duration at point s (weather-adjusted): setup + flight * mult_p
    drone_dur = {}
    for oi, o in enumerate(drone_opts):
        s = o["launch"]
        drone_dur[oi] = quicksum(
            (cfg["drone_setup_minutes"] + o["flight"] * weather[p]["drone"]) * w[(s, p)]
            for p in range(W)
        )

    # Boat trip duration (weather-adjusted): setup + (travel + unloads) * mult
    # Approximate: apply multiplier to whole trip duration
    boat_dur = {}
    for r in ramps:
        for ti, (seq, dur) in enumerate(trips_by_ramp[r]):
            boat_dur[(r, ti)] = quicksum(dur * weather[p]["boat"] * w[(r, p)] for p in range(W))

    # Departure time: D_s = T_s + truck_fixed + truck service + drone activities + boat activities
    for s in S:
        truck_svc = quicksum(
            cfg["truck_service_minutes_per_kg"] * shelters[h]["demand"] * z[(h, s)]
            for h in Hdry
            if (h, s) in z
        )
        drone_act = quicksum(
            drone_dur[oi] * d[(o["shelter"], oi)]
            for oi, o in enumerate(drone_opts)
            if o["launch"] == s
        )
        boat_act = quicksum(
            boat_dur[(r, ti)] * trip_used[(r, ti)]
            for r in ramps
            if r == s
            for ti in range(K[r])
        )
        if s == depot:
            model.addCons(
                D[s] >= T[s] + cfg["truck_fixed_stop_minutes"] + truck_svc + drone_act + boat_act,
                name=f"dep_{s}",
            )
        else:
            model.addCons(
                D[s] >= T[s] + cfg["truck_fixed_stop_minutes"] + truck_svc + drone_act + boat_act,
                name=f"dep_{s}",
            )
            # If not visited, D_s can be 0; force D_s = 0 when y_s = 0
            model.addCons(D[s] <= M * y[s], name=f"dep0_{s}")

    # Successor arrival uses departure of predecessor
    for a in S:
        for bb in S:
            if a == bb or (a, bb) not in x:
                continue
            t = etime.get((a, bb))
            if t is None:
                continue
            if bb == depot:
                model.addCons(T[bb] >= D[a] + t - M * (1 - x[(a, bb)]), name=f"tarr2_{a}_{bb}")
            else:
                model.addCons(T[bb] >= D[a] + t - M * (1 - x[(a, bb)]), name=f"tarr2_{a}_{bb}")

    # Completion time of depot return: T[depot] is 0 at start; return time is D[last]+t.
    # Define completion variable = arrival back at depot.
    comp = model.addVar(name="completion", vtype="C", lb=0, ub=M)
    for a in S:
        if a == depot:
            continue
        t = etime.get((a, depot))
        if t is not None and (a, depot) in x:
            model.addCons(comp >= D[a] + t - M * (1 - x[(a, depot)]), name=f"comp_{a}")

    # Shelter completion times
    for h in Hdry:
        s = shelters[h]["dry_node"]
        if (h, s) in z:
            model.addCons(
                C[h] >= D[s] + cfg["truck_fixed_stop_minutes"] + cfg["truck_service_minutes_per_kg"] * shelters[h]["demand"]
                - M * (1 - z[(h, s)]),
                name=f"Ch_{h}",
            )
    for oi, o in enumerate(drone_opts):
        h = o["shelter"]
        s = o["launch"]
        risk_pen = cfg["risk_penalty_minutes_per_point"] * o["risk"]
        model.addCons(
            C[h] >= D[s] + drone_dur[oi] + risk_pen - M * (1 - d[(h, oi)]),
            name=f"Chd_{h}_{oi}",
        )
    for r in ramps:
        for ti, (seq, dur) in enumerate(trips_by_ramp[r]):
            # position time of each shelter in the trip
            prev = r
            for pos, h in enumerate(seq):
                t = btime(prev, h)
                if t is None:
                    t = 0.0
                # time from trip start to reaching h: travel so far + unloads of previous shelters
                travel_so_far = 0.0
                p2 = r
                for h2 in seq[: pos + 1]:
                    travel_so_far += btime(p2, h2)
                    p2 = h2
                unload_before = cfg["boat_unload_minutes_per_shelter"] * pos
                # completion of h = D_r + setup + travel_so_far + unload_before + unload_h (approx: +4)
                base = cfg["boat_setup_minutes"] + travel_so_far + unload_before + cfg["boat_unload_minutes_per_shelter"]
                model.addCons(
                    C[h] >= D[r] + base * quicksum(weather[p]["boat"] * w[(r, p)] for p in range(W))
                    - M * (1 - b[(h, r, ti)]),
                    name=f"Chb_{h}_{r}_{ti}",
                )
                prev = h

    # Lateness
    for h in H:
        model.addCons(L[h] >= C[h] - shelters[h]["deadline"], name=f"lat_{h}")

    # ------------------------------------------------------------------
    # Objective
    # ------------------------------------------------------------------
    obj_terms = [comp]
    for h in H:
        wgt = weights.get(shelters[h]["priority"], 1.0)
        obj_terms.append(cfg["late_penalty_per_weighted_minute"] * wgt * L[h])
    model.setObjective(quicksum(obj_terms), sense="minimize")

    # ------------------------------------------------------------------
    # Solve
    # ------------------------------------------------------------------
    print("Solving...")
    try:
        model.optimize()
    except Exception as e:
        print(f"Solver error: {e}")

    status = model.getStatus()
    print(f"Status: {status}")
    nsols = model.getNSols()
    print(f"NSols: {nsols}")
    if nsols > 0:
        print(f"Objective: {model.getObjVal():.8f}")

    # ------------------------------------------------------------------
    # Extract solution
    # ------------------------------------------------------------------
    rows = []
    if nsols > 0:
        sol = model.getBestSol()

        # Truck route: follow x from depot
        route = [depot]
        cur = depot
        while True:
            nxt = None
            for bb in S:
                if bb == cur:
                    continue
                if (cur, bb) in x and model.getVal(x[(cur, bb)]) > 0.5:
                    nxt = bb
                    break
            if nxt is None or nxt == depot:
                break
            route.append(nxt)
            cur = nxt
        if route[-1] != depot:
            route.append(depot)

        for i, s in enumerate(route):
            rows.append({
                "row_type": "truck_stop",
                "sequence": i,
                "node_id": s,
                "trip_id": "",
                "mode": "",
                "shelter_id": "",
                "launch_node": "",
            })

        # Truck deliveries
        for (h, s), var in z.items():
            if model.getVal(var) > 0.5:
                rows.append({
                    "row_type": "delivery",
                    "sequence": "",
                    "node_id": s,
                    "trip_id": "",
                    "mode": "truck",
                    "shelter_id": h,
                    "launch_node": s,
                })
        # Drone deliveries
        for oi, o in enumerate(drone_opts):
            h = o["shelter"]
            if model.getVal(d[(h, oi)]) > 0.5:
                rows.append({
                    "row_type": "delivery",
                    "sequence": "",
                    "node_id": "",
                    "trip_id": f"DRONE_{oi}",
                    "mode": "drone",
                    "shelter_id": h,
                    "launch_node": o["launch"],
                })
        # Boat deliveries
        for r in ramps:
            for ti, (seq, dur) in enumerate(trips_by_ramp[r]):
                if model.getVal(trip_used[(r, ti)]) > 0.5:
                    for pos, h in enumerate(seq):
                        if model.getVal(b[(h, r, ti)]) > 0.5:
                            rows.append({
                                "row_type": "delivery",
                                "sequence": pos,
                                "node_id": "",
                                "trip_id": f"BOAT_{r}_{ti}",
                                "mode": "boat",
                                "shelter_id": h,
                                "launch_node": r,
                            })

    # ------------------------------------------------------------------
    # Validation
    # ------------------------------------------------------------------
    served = {}
    for row in rows:
        if row["row_type"] == "delivery":
            h = row["shelter_id"]
            served[h] = row

    ok = True
    for h in H:
        if h not in served:
            print(f"VALIDATION FAIL: shelter {h} not served")
            ok = False
    for h, row in served.items():
        if shelters[h]["area"] == "dry" and row["mode"] == "truck":
            if row["node_id"] != shelters[h]["dry_node"]:
                print(f"VALIDATION FAIL: dry shelter {h} served at wrong node")
                ok = False
        if shelters[h]["area"] == "flooded" and row["mode"] == "truck":
            print(f"VALIDATION FAIL: flooded shelter {h} served by truck")
            ok = False

    # Truck route check
    truck_stops = [r for r in rows if r["row_type"] == "truck_stop"]
    if truck_stops:
        if truck_stops[0]["node_id"] != depot or truck_stops[-1]["node_id"] != depot:
            print("VALIDATION FAIL: truck route does not start/end at depot")
            ok = False
        seqs = [int(r["sequence"]) for r in truck_stops]
        if seqs != list(range(len(seqs))):
            print("VALIDATION FAIL: truck sequence not increasing from 0")
            ok = False

    # Boat trip checks
    visited = set(r["node_id"] for r in truck_stops)
    boat_trips = {}
    for row in rows:
        if row["row_type"] == "delivery" and row["mode"] == "boat":
            tid = row["trip_id"]
            boat_trips.setdefault(tid, []).append(row)
    for tid, tr in boat_trips.items():
        launch = tr[0]["launch_node"]
        if launch not in visited:
            print(f"VALIDATION FAIL: boat trip {tid} launched from unvisited {launch}")
            ok = False
        load = sum(shelters[r["shelter_id"]]["demand"] for r in tr)
        if load > cfg["boat_capacity_kg"] + 1e-9:
            print(f"VALIDATION FAIL: boat trip {tid} over capacity {load}")
            ok = False
        seqs = [int(r["sequence"]) for r in tr]
        if seqs != list(range(len(seqs))):
            print(f"VALIDATION FAIL: boat trip {tid} sequence invalid")
            ok = False
        for r in tr:
            if shelters[r["shelter_id"]]["area"] != "flooded":
                print(f"VALIDATION FAIL: boat trip {tid} serves non-flooded {r['shelter_id']}")
                ok = False

    # Drone checks
    for row in rows:
        if row["row_type"] == "delivery" and row["mode"] == "drone":
            launch = row["launch_node"]
            if launch not in visited:
                print(f"VALIDATION FAIL: drone {row['shelter_id']} launched from unvisited {launch}")
                ok = False
            if staging[launch]["clearance"] == "poor":
                print(f"VALIDATION FAIL: drone launched from poor clearance {launch}")
                ok = False

    print(f"Validation: {'PASS' if ok else 'FAIL'}")

    # Completion/lateness audit
    if nsols > 0:
        for h in H:
            cv = model.getVal(C[h])
            lv = model.getVal(L[h])
            print(f"  {h}: C={cv:.4f} deadline={shelters[h]['deadline']} L={lv:.4f}")

    # ------------------------------------------------------------------
    # Write solution
    # ------------------------------------------------------------------
    os.makedirs(OUT_DIR, exist_ok=True)
    header = ["row_type", "sequence", "node_id", "trip_id", "mode", "shelter_id", "launch_node"]
    with open(SOL_PATH, "w", newline="") as f:
        wtr = csv.DictWriter(f, fieldnames=header)
        wtr.writeheader()
        for row in rows:
            out = {}
            for k in header:
                v = row.get(k, "")
                if v is None:
                    v = ""
                out[k] = v
            wtr.writerow(out)
    print(f"Wrote {SOL_PATH} with {len(rows)} rows")

    model.free()


if __name__ == "__main__":
    main()
